#include <stdio.h>

/* teste do desafio fora-da-faixa — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario escreve num arquivo o que a pessoa "digitaria", aponta o
   stdin para esse arquivo (freopen) e captura o stdout no proprio teste.
   Os nomes dos arquivos temporarios sao POR CENARIO: um cenario nunca le
   a entrada nem a captura do outro. Nunca ha fclose de stdin/stdout — so
   fflush — para o segundo freopen ficar legal (C11 7.21.4). */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void foraDaFaixa(void);

SM_TEST(o_zero_esta_fora) {
    /* o que a pessoa digita: 0 — abaixo do comeco da faixa */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "0\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    foraDaFaixa();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o 0 esta fora da faixa", linha, "fora da faixa\n",
              "0 nao chega a 1: a faixa inteira e falsa, e o ! a vira em verdadeira");
    /* a saida TERMINA na primeira linha — buffer novo com sentinel */
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "o aviso e uma linha so");
    fclose(f);
}

SM_TEST(o_cinquenta_esta_dentro) {
    /* 50 esta na faixa: a funcao nao pode imprimir nada */
    FILE *e = fopen("sm_entrada_2.tmp", "w");
    fprintf(e, "50\n");
    fclose(e);
    freopen("sm_entrada_2.tmp", "r", stdin);

    freopen("sm_saida_2.tmp", "w", stdout);
    foraDaFaixa();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o 50 nao gera aviso", linha, "(nada impresso)",
              "dentro da faixa a condicao negada e falsa: o bloco do aviso nao roda");
    fclose(f);
}

SM_TEST(o_cento_e_um_esta_fora) {
    /* 101 passou do fim da faixa: o aviso volta */
    FILE *e = fopen("sm_entrada_3.tmp", "w");
    fprintf(e, "101\n");
    fclose(e);
    freopen("sm_entrada_3.tmp", "r", stdin);

    freopen("sm_saida_3.tmp", "w", stdout);
    foraDaFaixa();
    fflush(stdout);

    FILE *f = fopen("sm_saida_3.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o 101 esta fora da faixa", linha, "fora da faixa\n",
              "101 passou de 100: o segundo lado do && e falso, e o ! avisa");
    fclose(f);
}

